+
+      form {
+        display: grid;
+        gap: 1.25rem;
+      }
+
+      fieldset {
+        margin: 0;
+        padding: 0;
+        border: 0;
+        min-width: 0;
+      }
+
+      legend {
+        margin-bottom: 0.75rem;
+        font-weight: 700;
+      }
+
+      .required {
+        color: var(--accent);
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.5rem;
+        padding: 1rem;
+        border: 1px solid var(--panel-border);
+        border-radius: 1rem;
+        background: #0f172a;
+      }
+
+      .checkbox-row {
+        display: flex;
+        align-items: start;
+        gap: 0.75rem;
+      }
+
+      input[type="checkbox"] {
+        width: 1.15rem;
+        height: 1.15rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--accent-strong);
+      }
+
+      label {
+        font-weight: 600;
+        line-height: 1.45;
+      }
+
+      .helper-text {
+        margin: 0;
+        font-size: 0.95rem;
+      }
+
+      button {
+        border: 0;
+        border-radius: 0.9rem;
+        padding: 0.95rem 1.1rem;
+        font: inherit;
+        font-weight: 700;
+        color: #020617;
+        background: linear-gradient(180deg, #bae6fd 0%, var(--accent-strong) 100%);
+        cursor: pointer;
+        transition: transform 160ms ease, filter 160ms ease;
+      }
+
+      button:hover {
+        transform: translateY(-1px);
+        filter: brightness(1.05);
+      }
+
+      button:focus-visible,
+      input:focus-visible {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 0;
+        color: #bfdbfe;
+        font-size: 0.95rem;
+      }
+
+      @media (max-width: 420px) {
+        .card {
+          padding: 1.5rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        :root {
+          --bg: Canvas;
+          --panel: Canvas;
+          --panel-border: ButtonBorder;
+          --text: CanvasText;
+          --muted: CanvasText;
+          --accent: Highlight;
+          --accent-strong: ButtonFace;
+          --focus: Highlight;
+          --shadow: none;
+        }
+
+        .skip-link,
+        .card,
+        .form-field,
+        button {
+          border: 1px solid ButtonBorder;
+        }
+
+        button {
+          color: ButtonText;
+          background: ButtonFace;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <main id="main-content"></main>
+    <script>
+      function FormField() {
+        return `
+          <div class="form-field">
+            <div class="checkbox-row">
+              <input
+                id="terms"
+                name="terms"
+                type="checkbox"
+                required
+                aria-required="true"
+                aria-describedby="terms-helper"
+              />
+              <label for="terms">I agree to the Terms of Use <span class="required" aria-hidden="true">*</span></label>
+            </div>
+            <p class="helper-text" id="terms-helper">Required to continue with submission.</p>
+          </div>
+        `;
+      }
+
+      function ConsentForm() {
+        return `
+          <form id="consent-form">
+            <fieldset>
+              <legend>Consent</legend>
+              ${FormField()}
+            </fieldset>
+            <button type="submit">Submit</button>
+            <p class="status" id="status-message" aria-live="polite"></p>
+          </form>
+        `;
+      }
+
+      function App() {
+        return `
+          <section class="card" aria-labelledby="page-title">
+            <h1 id="page-title">Confirm your agreement</h1>
+            <p>Review the terms and confirm consent before sending the form.</p>
+            ${ConsentForm()}
+          </section>
+        `;
+      }
+
+      const root = document.querySelector("main");
+      root.innerHTML = App();
+
+      const form = document.getElementById("consent-form");
+      const checkbox = document.getElementById("terms");
+      const statusMessage = document.getElementById("status-message");
+
+      checkbox.addEventListener("invalid", function () {
+        checkbox.setAttribute("aria-invalid", "true");
+      });
+
+      checkbox.addEventListener("change", function () {
+        checkbox.removeAttribute("aria-invalid");
+        statusMessage.textContent = "";
+      });
+
+      form.addEventListener("submit", function (event) {
+        event.preventDefault();
+
+        if (!form.reportValidity()) {
+          checkbox.setAttribute("aria-invalid", "true");
+          checkbox.focus();
+          statusMessage.textContent = "Please agree to the Terms of Use before submitting.";
+          return;
+        }
+
+        checkbox.removeAttribute("aria-invalid");
+        statusMessage.textContent = "Consent recorded successfully.";
+      });
+    </script>
+  </body>
+</html>
*** End Patch
